function renderRepairs(){const list=[...db.repairs].sort((a,b)=>a.date.localeCompare(b.date));const planned=list.filter(x=>x.status!=="done").reduce((s,x)=>s+Number(x.planned||0),0),actual=list.filter(x=>x.status==="done").reduce((s,x)=>s+Number(x.actual||0),0);$("#repairSummary").innerHTML=[["Запланировано",list.filter(x=>x.status==="planned").length],["В процессе",list.filter(x=>["parts","service","repair"].includes(x.status)).length],["Плановая сумма",money(planned)],["Факт",money(actual)]].map(x=>`<div class="summary-card"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join("");$("#repairList").innerHTML=list.map(r=>{const c=car(r.carId);return `<article class="list-item"><div class="top"><div><h3>${r.title}</h3><p>${model(c).brand} ${model(c).model} · ${c.plate} · ${date(r.date)}</p></div><strong>${money(r.status==="done"?r.actual:r.planned)}</strong></div><p>${r.service||""} ${r.note||""}</p><span class="badge ${r.status==="done"?"done":""}">${r.status}</span><div class="item-actions"><button class="btn" onclick="editRepair('${r.id}')">Редактировать</button><button class="btn danger" onclick="deleteRepair('${r.id}')">Удалить</button></div></article>`}).join("")||`<div class="card">Ремонтов нет</div>`}

function taxSettings(){
 db.settings.tax=db.settings.tax||{vat:"no",method:"ryczalt",ryczaltRate:8.5,monthlyContributions:0,deductVatCosts:true};
 return db.settings.tax
}
function periodBounds(period){
 const now=new Date(),year=now.getFullYear(),month=now.getMonth();
 if(period==="month")return{from:new Date(year,month,1),to:new Date(year,month+1,0),months:1};
 if(period==="year")return{from:new Date(year,0,1),to:new Date(year,11,31),months:12};
 return{from:null,to:null,months:Math.max(1,Math.ceil((new Date()-new Date(Math.min(...db.payments.map(p=>new Date(p.to||p.date||today()).getTime()),Date.now())))/2629800000))}
}
function inPeriod(dateValue,bounds){
 if(!dateValue)return false;
 const d=new Date(dateValue+"T12:00:00");
 return(!bounds.from||d>=bounds.from)&&(!bounds.to||d<=bounds.to)
}
function financialData(period,carId=null){
 const bounds=periodBounds(period);
 const payments=db.payments.filter(p=>(!carId||p.carId===carId)&&inPeriod(p.date||p.to,bounds));
 const repairs=db.repairs.filter(r=>(!carId||r.carId===carId)&&r.status==="done"&&inPeriod(r.date,bounds));
 const paidExpenses=db.expenses.filter(x=>(!carId||x.carId===carId)&&x.status==="paid"&&inPeriod(x.date,bounds));
 const grossRevenue=payments.reduce((s,p)=>s+Number(p.received||0),0);
 const repairGross=repairs.reduce((s,r)=>s+Number(r.actual||r.planned||0),0);
 const otherGross=paidExpenses.reduce((s,x)=>s+Number(x.amount||0),0);
 const grossCosts=repairGross+otherGross;
 const tax=taxSettings(),vatPayer=tax.vat==="yes",vatFactor=1.23;
 const netRevenue=vatPayer?grossRevenue/vatFactor:grossRevenue;
 const deductibleGross=vatPayer&&tax.deductVatCosts;
 const netCosts=deductibleGross?grossCosts/vatFactor:grossCosts;
 const outputVat=vatPayer?grossRevenue-netRevenue:0;
 const inputVat=deductibleGross?grossCosts-netCosts:0;
 const vatDue=Math.max(0,outputVat-inputVat);
 const profitBeforePit=netRevenue-netCosts;
 let pit=0;
 if(tax.method==="ryczalt")pit=Math.max(0,netRevenue*Number(tax.ryczaltRate||0)/100);
 else if(tax.method==="linear")pit=Math.max(0,profitBeforePit*.19);
 else{
  if(period==="month")pit=Math.max(0,profitBeforePit*.12-300);
  else{
   const base=Math.max(0,profitBeforePit);
   pit=base<=120000?Math.max(0,base*.12-3600):10800+(base-120000)*.32
  }
 }
 const contributions=Number(tax.monthlyContributions||0)*bounds.months;
 const finalProfit=grossRevenue-grossCosts-vatDue-pit-contributions;
 return{grossRevenue,repairGross,otherGross,grossCosts,netRevenue,netCosts,vatDue,pit,contributions,finalProfit,profitBeforePit}
}
function renderProfitability(){
 const period=$("#profitPeriod")?.value||"month",tax=taxSettings(),data=financialData(period);
 $("#profitSummary").innerHTML=[
  ["Оплата аренды",money(data.grossRevenue),"good"],
  ["Ремонты и расходы",money(data.grossCosts),"danger"],
  ["VAT к оплате",money(data.vatDue),""],
  ["PIT",money(data.pit),""],
  ["Фактическая прибыль",money(data.finalProfit),data.finalProfit>=0?"good":"danger"]
 ].map(x=>`<div class="summary-card ${x[2]}"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join("");
 $("#taxVat").value=tax.vat;
 $("#taxMethod").value=tax.method;
 $("#taxRyczaltRate").value=tax.ryczaltRate;
 $("#taxMonthlyContributions").value=tax.monthlyContributions;
 $("#taxDeductVatCosts").checked=tax.deductVatCosts!==false;
 $("#carProfitability").innerHTML=db.cars.map(c=>{
  const d=financialData(period,c.id),m=model(c);
  return `<div class="profitability-row"><div><strong>${m.brand} ${m.model}</strong><small>${c.plate}</small></div><span>Аренда ${money(d.grossRevenue)}</span><span>Ремонты ${money(d.repairGross)}</span><span>После налогов ${money(d.finalProfit)}</span></div>`
 }).join("");
}

function renderPayments(){renderProfitability();const total=db.payments.reduce((s,p)=>s+p.received,0),expected=db.payments.reduce((s,p)=>s+p.expected,0),debt=expected-total;$("#paymentSummary").innerHTML=[["Ожидалось",money(expected)],["Получено",money(total)],["Задолженность",money(debt)],["Записей",db.payments.length]].map(x=>`<div class="summary-card"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join("");$("#paymentList").innerHTML=[...db.payments].sort((a,b)=>b.to.localeCompare(a.to)).map(p=>{const c=car(p.carId),s=paymentStatus(p),rest=Math.max(0,p.expected-p.received);return `<article class="list-item"><div class="top"><div><h3>${model(c).brand} ${model(c).model} · ${c.plate}</h3><p>${p.tenant||c.tenant||"Без арендатора"} · ${date(p.from)} — ${date(p.to)} · ${p.week||""}</p></div><strong>${money(p.received)}</strong></div><p>Ожидалось ${money(p.expected)} · Осталось ${money(rest)}</p><span class="badge ${s}">${paymentStatusText(s)}</span><div class="item-actions"><button class="btn" onclick="editPayment('${p.id}')">Редактировать</button><button class="btn danger" onclick="deletePayment('${p.id}')">Удалить</button></div></article>`}).join("")||`<div class="card">Оплат пока нет</div>`}
function renderExpenses(){const active=db.expenses.filter(x=>x.status==="planned"),sum=active.reduce((s,x)=>s+x.amount,0);$("#expenseSummary").innerHTML=[["Запланировано",active.length],["Плановая сумма",money(sum)],["Оплачено",db.expenses.filter(x=>x.status==="paid").length],["Отменено",db.expenses.filter(x=>x.status==="cancelled").length]].map(x=>`<div class="summary-card"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join("");$("#expenseList").innerHTML=[...db.expenses].sort((a,b)=>a.date.localeCompare(b.date)).map(x=>{const c=car(x.carId);return `<article class="list-item"><div class="top"><div><h3>${x.title}</h3><p>${model(c).brand} ${model(c).model} · ${c.plate} · ${date(x.date)}</p></div><strong>${money(x.amount)}</strong></div><p>${x.category} · ${x.note||""}</p><span class="badge ${x.status==="paid"?"paid":""}">${x.status}</span><div class="item-actions"><button class="btn" onclick="editExpense('${x.id}')">Редактировать</button><button class="btn danger" onclick="deleteExpense('${x.id}')">Удалить</button></div></article>`}).join("")||`<div class="card">Плановых расходов нет</div>`}
function addMonthsIso(dateValue,months){const d=new Date(dateValue+"T12:00:00");d.setMonth(d.getMonth()+months);return d.toISOString().slice(0,10)}
function buildInsuranceInstallments(total,count,firstDate,frequency,existing=[]){const step=frequency==="quarterly"?3:1,amount=Math.round((Number(total||0)/Math.max(1,count))*100)/100;return Array.from({length:count},(_,i)=>{const old=existing[i],finalAmount=i===count-1?Math.round((Number(total||0)-amount*(count-1))*100)/100:amount;return{id:old?.id||uid(),number:i+1,due:addMonthsIso(firstDate,i*step),amount:finalAmount,paid:old?.paid||false,paidDate:old?.paidDate||""}})}
function installmentSummary(doc){const list=doc.installments||[],paid=list.filter(x=>x.paid).reduce((s,x)=>s+Number(x.amount||0),0),next=list.filter(x=>!x.paid).sort((a,b)=>a.due.localeCompare(b.due))[0];return{paid,left:Math.max(0,Number(doc.cost||0)-paid),next}}
function toggleInsuranceInstallment(documentId,installmentId){const doc=db.documents.find(x=>x.id===documentId),item=doc?.installments?.find(x=>x.id===installmentId);if(!item)return;item.paid=!item.paid;item.paidDate=item.paid?today():"";save();renderDocuments();if(selectedCarId)openCar(selectedCarId)}

function allEvents(){
 const result=[];
 for(const c of fleetCars()){
  const m=model(c);
  if(c.insurance)result.push({date:c.insurance,carId:c.id,title:"Окончание страховки",type:"insurance",car:m.brand+" "+m.model+" · "+c.plate});
  if(c.inspection)result.push({date:c.inspection,carId:c.id,title:"Техосмотр",type:"inspection",car:m.brand+" "+m.model+" · "+c.plate});
 }
 for(const r of db.repairs.filter(x=>x.status!=="done"))result.push({date:r.date,carId:r.carId,title:r.title,type:"repair",car:model(car(r.carId)).brand+" "+model(car(r.carId)).model+" · "+car(r.carId).plate});
 for(const x of db.expenses.filter(x=>x.status==="planned"))result.push({date:x.date,carId:x.carId,title:x.title,type:"expense",car:model(car(x.carId)).brand+" "+model(car(x.carId)).model+" · "+car(x.carId).plate,amount:x.amount});
 for(const d of db.documents){
  for(const i of d.installments||[])if(!i.paid)result.push({date:i.due,carId:d.carId,title:`${d.title}: рата ${i.number}`,type:"installment",car:model(car(d.carId)).brand+" "+model(car(d.carId)).model+" · "+car(d.carId).plate,amount:i.amount});
  if(d.expiry)result.push({date:d.expiry,carId:d.carId,title:`Документ: ${d.title}`,type:"document",car:model(car(d.carId)).brand+" "+model(car(d.carId)).model+" · "+car(d.carId).plate});
 }
 return result.filter(x=>x.date).map(x=>({...x,days:days(x.date)}))
}
function eventsForCar(carId){return allEvents().filter(x=>x.carId===carId)}
function eventIcon(type){return{insurance:"🛡️",inspection:"🔍",repair:"🔧",expense:"💰",installment:"💳",document:"📄"}[type]||"📅"}
function renderCalendar(){
 const range=Number($("#calendarRange")?.value||90);
 const events=allEvents().filter(x=>x.days>=0&&x.days<=range).sort((a,b)=>a.date.localeCompare(b.date));
 const overdue=allEvents().filter(x=>x.days<0).length;
 $("#calendarSummary").innerHTML=[
  ["Ближайшие 7 дней",events.filter(x=>x.days<=7).length],
  ["Ближайшие 30 дней",events.filter(x=>x.days<=30).length],
  ["Всего в периоде",events.length],
  ["Просрочено",overdue]
 ].map(x=>`<div class="summary-card"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join("");
 $("#calendarList").innerHTML=events.length?events.map(e=>`<article class="calendar-item ${e.days<=7?"urgent":e.days<=30?"soon":""}">
  <div class="calendar-date"><strong>${date(e.date)}</strong><small>${e.days===0?"Сегодня":`через ${e.days} дн.`}</small></div>
  <div class="calendar-icon">${eventIcon(e.type)}</div>
  <div><h3>${e.title}</h3><p>${e.car}${e.amount?` · ${money(e.amount)}`:""}</p></div>
 </article>`).join(""):`<div class="card">На выбранный период событий нет</div>`;
}

function renderDocuments(){const expired=db.documents.filter(x=>x.expiry&&days(x.expiry)<0).length,soon=db.documents.filter(x=>x.expiry&&days(x.expiry)>=0&&days(x.expiry)<=30).length;$("#documentSummary").innerHTML=[["Всего",db.documents.length],["Истекают ≤30 дней",soon],["Просрочены",expired],["Без срока",db.documents.filter(x=>!x.expiry).length]].map(x=>`<div class="summary-card"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join("");$("#documentList").innerHTML=db.documents.map(d=>{const c=car(d.carId),left=d.expiry?days(d.expiry):null;return `<article class="doc-card"><h3>${d.title}</h3><p>${model(c).brand} ${model(c).model} · ${c.plate}</p><div class="doc-row"><span>Тип</span><strong>${d.type}</strong></div><div class="doc-row"><span>Номер</span><strong>${d.number||"—"}</strong></div><div class="doc-row"><span>До</span><strong>${d.expiry?date(d.expiry)+" · "+left+" дн.":"Без срока"}</strong></div><div class="doc-row"><span>Стоимость</span><strong>${money(d.cost)}</strong></div>${d.type==="insurance"&&d.paymentMode==="installments"?(()=>{const s=installmentSummary(d);return `<div class="insurance-summary"><span>Оплачено ${money(s.paid)}</span><span>Осталось ${money(s.left)}</span><span>${s.next?`Следующая: ${date(s.next.due)}`:"Все раты оплачены"}</span></div><div class="installment-list">${(d.installments||[]).map(x=>`<button class="installment ${x.paid?"paid":""}" onclick="toggleInsuranceInstallment('${d.id}','${x.id}')"><span>Рата ${x.number}</span><strong>${money(x.amount)}</strong><small>${date(x.due)} · ${x.paid?"Оплачена":"Ожидает"}</small></button>`).join("")}</div>`})():""}<div class="item-actions"><button class="btn" onclick="editDocument('${d.id}')">Редактировать</button><button class="btn danger" onclick="deleteDocument('${d.id}')">Удалить</button></div></article>`}).join("")||`<div class="card">Документов нет</div>`}
function openCar(id){selectedCarId=id;const c=car(id),m=model(c),payments=db.payments.filter(x=>x.carId===id),received=payments.reduce((s,x)=>s+x.received,0),debt=payments.reduce((s,x)=>s+Math.max(0,x.expected-x.received),0),rep=db.repairs.filter(x=>x.carId===id),exp=db.expenses.filter(x=>x.carId===id);showPage("carPage");$("#carDetail").innerHTML=`<div class="detail-hero">
 <img src="${m.image}" alt="${m.brand} ${m.model}">
 <div class="detail-title"><h2>${m.brand} ${m.model}</h2><p>${c.plate} · ${c.tenant||"Без арендатора"}</p></div>
</div><div class="detail-grid"><div><div class="card"><h3>Пробег и обслуживание</h3><div class="metrics"><div class="metric"><small>Пробег</small><strong>${km(c.mileage)}</strong></div><div class="metric"><small>До масла</small><strong>${km(Math.max(0,oil(c)))}</strong></div><div class="metric"><small>Страховка</small><strong>${date(c.insurance)}</strong></div><div class="metric"><small>Техосмотр</small><strong>${date(c.inspection)}</strong></div></div><button class="btn full" onclick="openMileage('${c.id}')">Обновить пробег</button><button class="btn full" onclick="openRepairDialog('${c.id}')">Запланировать ремонт</button></div><div class="card" style="margin-top:12px"><h3>Ремонты</h3>${rep.map(x=>`<p>${date(x.date)} · ${x.title} · ${money(x.planned)}</p>`).join("")||"Нет записей"}</div></div><div><div class="card"><h3>Аренда</h3><p>Ставка: <strong>${money(c.weeklyRent)} / нед.</strong></p><p>Получено: <strong>${money(received)}</strong></p><p>Долг: <strong>${money(debt)}</strong></p><p>Прибыль за месяц после ремонтов и налогов: <strong>${money(financialData("month",c.id).finalProfit)}</strong></p><p>Прибыль за год: <strong>${money(financialData("year",c.id).finalProfit)}</strong></p><button class="btn primary full" onclick="openPaymentDialog('${c.id}')">Добавить оплату</button></div><div class="card" style="margin-top:12px"><h3>Страховка в рассрочку</h3>${db.documents.filter(d=>d.carId===c.id&&d.type==="insurance"&&d.paymentMode==="installments").map(d=>{const s=installmentSummary(d);return `<p>${d.title}: оплачено ${money(s.paid)}, осталось ${money(s.left)}${s.next?`, следующая рата ${date(s.next.due)}`:""}</p>`}).join("")||"Нет страховых рат"}</div><div class="card" style="margin-top:12px"><h3>Плановые расходы</h3>${exp.map(x=>`<p>${date(x.date)} · ${x.title} · ${money(x.amount)}</p>`).join("")||"Нет записей"}</div><div class="card" style="margin-top:12px"><button class="btn full" onclick="openCarDialog('${c.id}')">Редактировать авто</button><button class="btn danger full" onclick="deleteCar('${c.id}')">Удалить авто</button></div></div></div>`}
function requireFleetCar(){if(fleetCars().length)return true;toast("Сначала добавьте автомобиль в автопарк");return false}
